// Package replyconformance holds the stock client's REQUIRED reply paths and
// checks a successful reply against them. The obligations are generated by
// tools/reply_consumers.py; a reply is never altered by this package.
package replyconformance

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"reflect"
	"strconv"
	"strings"
	"sync"
)

//go:embed reply_consumers.json
var generated []byte

const requiredCode = 1

type step struct {
	key    string
	list   bool
	parent string
}

type obligation struct {
	paths        []string
	steps        [][]step
	requirements map[string]int
}

// midObligations holds one MID's unconditional paths plus, when the generated
// evidence names a discriminator, one obligation set per discriminator value.
// A branch the extractor could not attribute is kept in its own UNKNOWN bucket
// and is never selected by a reply.
type midObligations struct {
	unconditional obligation
	discriminator string
	branches      map[string]obligation
}

var (
	loadOnce      sync.Once
	requiredByMID map[uint16]midObligations
	fieldIndexes  sync.Map
)

// Checker implements the HTTP edge conformance hook. Check reports a violation
// for each REQUIRED path the reply omits or sends as JSON null.
type Checker struct{}

func (Checker) Check(mid uint16, reply any) []string {
	loadOnce.Do(load)
	record, present := requiredByMID[mid]
	if !present {
		return nil
	}
	var violations []string
	check(record.unconditional, reply, &violations)
	if record.discriminator == "" {
		return violations
	}
	value, present := discriminatorValue(reply, record.discriminator)
	if !present {
		return violations
	}
	branch, present := record.branches[value]
	if !present {
		return violations
	}
	check(branch, reply, &violations)
	return violations
}

func check(record obligation, reply any, violations *[]string) {
	for index, steps := range record.steps {
		walk(steps, reply, record.paths[index], record.requirements, violations)
	}
}

func discriminatorValue(reply any, key string) (string, bool) {
	value, present := member(reply, key)
	if !present || isNil(value) {
		return "", false
	}
	switch typed := value.(type) {
	case string:
		return typed, true
	case json.Number:
		return typed.String(), true
	case float64:
		return strconv.FormatInt(int64(typed), 10), true
	case float32:
		return strconv.FormatInt(int64(typed), 10), true
	case int:
		return strconv.Itoa(typed), true
	case int8, int16, int32, int64:
		return fmt.Sprintf("%d", typed), true
	case uint, uint8, uint16, uint32, uint64:
		return fmt.Sprintf("%d", typed), true
	}
	return "", false
}

// Reporter is the part of *testing.T the test helper needs, so production
// code can import this package without linking the test framework.
type Reporter interface {
	Helper()
	Fatalf(format string, args ...any)
}

// Check fails the test when a successful reply lacks a REQUIRED client path.
func Check(t Reporter, mid uint16, body any) {
	t.Helper()
	for _, path := range (Checker{}).Check(mid, body) {
		t.Fatalf("MID %d reply is missing required path %q", mid, path)
	}
}

type branchRecord struct {
	Status string            `json:"status"`
	Paths  []json.RawMessage `json:"paths"`
}

func load() {
	var document struct {
		MIDs map[string]struct {
			Paths    []json.RawMessage                  `json:"paths"`
			Branches map[string]map[string]branchRecord `json:"branches"`
		} `json:"mids"`
	}
	if err := json.Unmarshal(generated, &document); err != nil {
		panic("replyconformance: embedded obligations: " + err.Error())
	}
	requiredByMID = make(map[uint16]midObligations)
	for text, record := range document.MIDs {
		number, err := strconv.ParseUint(text, 10, 16)
		if err != nil {
			continue
		}
		entry := midObligations{unconditional: parseObligation(record.Paths)}
		for discriminator, values := range record.Branches {
			entry.discriminator = discriminator
			entry.branches = make(map[string]obligation, len(values))
			for value, branch := range values {
				if branch.Status == "UNKNOWN" {
					continue
				}
				entry.branches[value] = parseObligation(branch.Paths)
			}
		}
		if len(entry.unconditional.paths) > 0 || len(entry.branches) > 0 {
			requiredByMID[uint16(number)] = entry
		}
	}
}

func parseObligation(rawPaths []json.RawMessage) obligation {
	current := obligation{requirements: map[string]int{}}
	var required []string
	for _, raw := range rawPaths {
		var entry []json.RawMessage
		if err := json.Unmarshal(raw, &entry); err != nil || len(entry) < 2 {
			continue
		}
		var path string
		var requirement int
		if json.Unmarshal(entry[0], &path) != nil || json.Unmarshal(entry[1], &requirement) != nil {
			continue
		}
		current.requirements[path] = requirement
		if requirement == requiredCode {
			required = append(required, path)
		}
	}
	for _, path := range required {
		current.paths = append(current.paths, path)
		current.steps = append(current.steps, parsePath(path))
	}
	return current
}

func parsePath(path string) []step {
	segments := strings.Split(path, ".")
	steps := make([]step, 0, len(segments))
	prefix := ""
	for _, segment := range segments {
		list := strings.HasSuffix(segment, "[]")
		key := strings.TrimSuffix(segment, "[]")
		own := key
		if prefix != "" {
			own = prefix + "." + key
		}
		steps = append(steps, step{key: key, list: list, parent: own})
		if prefix != "" {
			prefix += "."
		}
		prefix += segment
	}
	return steps
}

// walk checks one path. When a list this path descends into is absent, the
// list's own requirement decides (REPLY_CONFORMANCE_EDGE_V1 ruling 4): an
// optional parent makes the leaf inapplicable, a required parent reports.
func walk(steps []step, current any, path string, requirements map[string]int, violations *[]string) {
	first := steps[0]
	value, present := member(current, first.key)
	if !present || isNil(value) {
		if first.list && len(steps) > 1 && !requiredParent(requirements, first.parent) {
			return
		}
		*violations = append(*violations, path)
		return
	}
	if len(steps) == 1 {
		return
	}
	if first.list {
		for _, element := range elements(value) {
			walk(steps[1:], element, path, requirements, violations)
		}
		return
	}
	walk(steps[1:], value, path, requirements, violations)
}

func requiredParent(requirements map[string]int, parent string) bool {
	if parent == "" {
		return false
	}
	if code, present := requirements[parent]; present {
		return code == requiredCode
	}
	code, present := requirements[parent+"[]"]
	return present && code == requiredCode
}

func member(container any, key string) (any, bool) {
	if object, ok := container.(map[string]any); ok {
		value, present := object[key]
		return value, present
	}
	reflected := reflect.ValueOf(container)
	if !reflected.IsValid() {
		return nil, false
	}
	if reflected.Kind() == reflect.Pointer || reflected.Kind() == reflect.Interface {
		if reflected.IsNil() {
			return nil, false
		}
		return member(reflected.Elem().Interface(), key)
	}
	if reflected.Kind() == reflect.Map && reflected.Type().Key().Kind() == reflect.String {
		value := reflected.MapIndex(reflect.ValueOf(key))
		if !value.IsValid() {
			return nil, false
		}
		return value.Interface(), true
	}
	if reflected.Kind() != reflect.Struct {
		return nil, false
	}
	index, present := jsonFieldIndex(reflected.Type(), key)
	if !present {
		return nil, false
	}
	return reflected.FieldByIndex(index).Interface(), true
}

// jsonFieldIndex maps a JSON key to its field path, so the walker reads a
// typed reply exactly as encoding/json emits it.
func jsonFieldIndex(structType reflect.Type, key string) ([]int, bool) {
	if cached, ok := fieldIndexes.Load(structType); ok {
		index, present := cached.(map[string][]int)[key]
		return index, present
	}
	fields := map[string][]int{}
	for _, field := range reflect.VisibleFields(structType) {
		if field.PkgPath != "" {
			continue
		}
		name, _, _ := strings.Cut(field.Tag.Get("json"), ",")
		if name == "-" {
			continue
		}
		if name == "" {
			if field.Anonymous {
				continue
			}
			name = field.Name
		}
		if _, present := fields[name]; !present {
			fields[name] = field.Index
		}
	}
	fieldIndexes.Store(structType, fields)
	index, present := fields[key]
	return index, present
}

func elements(value any) []any {
	if list, ok := value.([]any); ok {
		return list
	}
	reflected := reflect.ValueOf(value)
	if !reflected.IsValid() {
		return nil
	}
	for reflected.Kind() == reflect.Pointer || reflected.Kind() == reflect.Interface {
		if reflected.IsNil() {
			return nil
		}
		reflected = reflected.Elem()
	}
	if reflected.Kind() != reflect.Slice && reflected.Kind() != reflect.Array {
		return nil
	}
	list := make([]any, reflected.Len())
	for index := range list {
		list[index] = reflected.Index(index).Interface()
	}
	return list
}

func isNil(value any) bool {
	if value == nil {
		return true
	}
	reflected := reflect.ValueOf(value)
	switch reflected.Kind() {
	case reflect.Chan, reflect.Func, reflect.Interface, reflect.Map, reflect.Pointer, reflect.Slice:
		return reflected.IsNil()
	}
	return false
}
